import type { ImageData_CropShape } from './../../ricos-schema/next-schema/index.js';

import { SHAPE_CROP_OPTIONS, type ShapeCropOption } from '../shape-crop-shapes.js';

const CROP_FRAME_PRESETS = [
  ['FRAME_ORIGINAL', 'ImageShapeCrop_Original', 'original'],
  ['FRAME_FREE_FORM', 'ImageShapeCrop_FreeForm'],
  ['FRAME_1_1', 'ImageShapeCrop_Ratio_1_1', 1],
  ['FRAME_16_9', 'ImageShapeCrop_Ratio_16_9', 16 / 9],
  ['FRAME_9_16', 'ImageShapeCrop_Ratio_9_16', 9 / 16],
  ['FRAME_5_4', 'ImageShapeCrop_Ratio_5_4', 5 / 4],
  ['FRAME_4_5', 'ImageShapeCrop_Ratio_4_5', 4 / 5],
  ['FRAME_4_3', 'ImageShapeCrop_Ratio_4_3', 4 / 3],
  ['FRAME_3_4', 'ImageShapeCrop_Ratio_3_4', 3 / 4],
  ['FRAME_3_2', 'ImageShapeCrop_Ratio_3_2', 3 / 2],
  ['FRAME_2_3', 'ImageShapeCrop_Ratio_2_3', 2 / 3],
] as const;

export type CropFramePresetId = (typeof CROP_FRAME_PRESETS)[number][0];

export type CropPresetId = CropFramePresetId | ImageData_CropShape;

export type CropFramePresetOption = {
  id: CropFramePresetId;
  kind: 'frame';
  labelKey: string;
  dataHook: string;
  aspectRatio?: number | 'original';
};

export type CropShapePresetOption = ShapeCropOption & {
  kind: 'shape';
};

export type CropPresetOption = CropFramePresetOption | CropShapePresetOption;

export const getCropFramePresetDataHook = (id: CropFramePresetId) =>
  `shape-crop-frame-option-${id.toLowerCase().replace(/_/g, '-')}`;

export const CROP_FRAME_PRESET_OPTIONS: CropFramePresetOption[] = CROP_FRAME_PRESETS.map(
  ([id, labelKey, aspectRatio]) => ({
    id,
    kind: 'frame',
    labelKey,
    dataHook: getCropFramePresetDataHook(id),
    aspectRatio,
  })
);

export const CROP_PRESET_OPTIONS: CropPresetOption[] = [
  ...CROP_FRAME_PRESET_OPTIONS,
  ...SHAPE_CROP_OPTIONS.map(option => ({
    ...option,
    kind: 'shape' as const,
  })),
];

export const resolveCropFrameAspectRatio = (
  preset: CropFramePresetOption,
  imageWidth: number | null | undefined,
  imageHeight: number | null | undefined
): number | null => {
  if (preset.aspectRatio === 'original') {
    return imageWidth && imageHeight ? imageWidth / imageHeight : null;
  }

  return preset.aspectRatio ?? null;
};
