/**
 * Turns inline SVG markup into a `data:` URI for use in CSS (`mask-image`,
 * `background-image`) or as an `<img>`/WDS `Thumbnail` source.
 *
 * Only the characters a `url("…")` value cannot carry literally are percent-encoded,
 * unlike `encodeURIComponent`, which also encodes `/ : = ,` and every space and so
 * roughly doubles the payload. That payload ends up in an inline `style` attribute of
 * every shape-cropped image, including the server-rendered markup.
 */
export const svgToDataUri = (svg: string): string =>
  `data:image/svg+xml,${svg
    .trim()
    .replace(/\s+/g, ' ')
    .replace(/[%#<>"]/g, char => `%${char.charCodeAt(0).toString(16).toUpperCase()}`)}`;
