import { Thumbnail } from '@wix/design-system';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';

import { CROP_PRESET_OPTIONS, type CropPresetId, type CropPresetOption } from './crop-presets.js';
import { CROP_PRESET_THUMBNAIL_DATA } from './crop-thumbnail-data.js';
import styles from './shape-crop-modal-scss.js';

export type CropPresetGridProps = {
  selectedId: CropPresetId;
  onSelect: (preset: CropPresetOption) => void;
};

/**
 * The crop preset thumbnails, split out of `shape-crop-modal.tsx` so `React.lazy` can keep
 * the 21 inlined thumbnail SVGs out of the eagerly loaded image plugin chunk — they are
 * only needed once the crop panel is open.
 */
const CropPresetGrid: React.FC<CropPresetGridProps> = ({ selectedId, onSelect }) => {
  const { t } = useContext(RicosContext);

  return (
    <div className={styles.grid}>
      {CROP_PRESET_OPTIONS.map(option => {
        const { id, dataHook, labelKey } = option;

        return (
          <Thumbnail
            key={id}
            className={styles.optionThumbnail}
            size="tiny"
            width="var(--thumbnail-size)"
            height="var(--thumbnail-size)"
            image={CROP_PRESET_THUMBNAIL_DATA[id]}
            title={t(labelKey)}
            textPosition="outside"
            selected={id === selectedId}
            hideSelectedIcon
            onClick={() => onSelect(option)}
            dataHook={dataHook}
            ariaLabel={t(labelKey)}
          />
        );
      })}
    </div>
  );
};

// oxlint-disable-next-line import/no-default-export
export default CropPresetGrid;
